const originalShowModal = HTMLDialogElement.prototype.showModal;

HTMLDialogElement.prototype.showModal = function () {
  originalShowModal.call(this);

  if (this.classList.contains('notify__popup')) {
    requestAnimationFrame(() => {
      this.scrollTop = 0;
    });
  }
};


(function () {
  function addDyslexiaTooltip() {
    var button = document.querySelector('.dyslexiahelper__btn');

    if (!button || button.dataset.tooltipReady) return;

    button.dataset.tooltipReady = 'true';

    var lang = document.documentElement.lang || 'en';

    var tooltip = document.createElement('div');
    tooltip.id = 'tooltip-dyslexiahelper';
    tooltip.className = 'tooltip__body';
    tooltip.textContent = lang === 'cy'
      ? 'Gosodiadau Dyslecsia'
      : 'Open dyslexia helper options';
    tooltip.setAttribute('role', 'tooltip');

    tooltip.style.cssText = `
      position: fixed;
      display: none;
      overflow: visible;
      width: max-content;
      min-width: 3rem;
      max-width: 20rem;
      color: #fff;
      font-size: .9rem;
      line-height: 1.5;
      padding: .5rem .75rem .55rem;
      background-color: rgba(0,0,0,0.85);
      border-radius: .35rem;
      z-index: 999999;
      pointer-events: none;
      white-space: nowrap;
      transform: translateX(-50%);
    `;

    var arrow = document.createElement('div');

    arrow.style.cssText = `
      position: absolute;
      top: -6px;
      left: 12px;
      transform: none;
      width: 0;
      height: 0;
      border-left: 6px solid transparent;
      border-right: 6px solid transparent;
      border-bottom: 6px solid rgba(0,0,0,0.85);
      display: block;
    `;

    tooltip.appendChild(arrow);
    document.body.appendChild(tooltip);

    button.setAttribute('aria-describedby', tooltip.id);

    function showTooltip() {
      var rect = button.getBoundingClientRect();

      tooltip.style.left =
        (rect.left + rect.width / 2 + 30) + 'px';

      tooltip.style.top = (rect.bottom + 16) + 'px';
      tooltip.style.display = 'block';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    button.addEventListener('mouseenter', showTooltip);
    button.addEventListener('mouseleave', hideTooltip);
    button.addEventListener('focus', showTooltip);
    button.addEventListener('blur', hideTooltip);
  }

  addDyslexiaTooltip();

  new MutationObserver(addDyslexiaTooltip).observe(document.body, {
    childList: true,
    subtree: true
  });
})();


